var t=`0614-chorba-frik`;var n=`world-0614`;var a=`DZ`;var s=`northern-africa`;var o=4;var r=61;var l={en:`Chorba Frik`,ua:`Чорба фрік`};var g={en:`Chorba Frik is a Algeria classic prepared with yellow onion, celery stalk, lamb, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Чорба фрік, страва кухні країни Алжир зі складниками: жовта цибуля, стебло селери, ягнятина, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,160,`g`],[`celery-stalk`,100,`g`],[`extra-virgin-olive-oil`,40,`ml`],[`lamb`,350,`g`],[`tomato`,270,`g`]]},{en:`Simmer cracked freekeh in the lamb-and-tomato broth until the grains have softened while retaining their smoky bite.`,ua:`Варіть подрібнений фріке у баранячо-томатному бульйоні, доки крупа пом’якне, але збереже характерний димний смак.`,t:[`stewing`],m:45,i:[[`freekeh`,210,`g`],[`chicken-stock`,1050,`ml`],[`canned-chickpeas`,170,`g`],[`ground-cinnamon`,3,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,20,`g`],[`lemon-juice`,30,`ml`]]}];var m={slug:t,id:n,country:`DZ`,region:s,servings:4,minutes:61,title:l,text:g,steps:h};export{a as country,m as default,n as id,r as minutes,s as region,o as servings,t as slug,h as steps,g as text,l as title};